# One-off / emergency image build on Cloud Build (free tier: 120 build-minutes a day).
# Normal deploys go through GitHub Actions (deploy.yml).
#   gcloud builds submit --config cloudbuild.yaml --substitutions=_APP_URL=https://...,_API_KEY=...,_APP_ID=... --project lsv-oss-prod
steps:
  - name: gcr.io/cloud-builders/docker
    args:
      - build
      - --build-arg=NEXT_PUBLIC_APP_URL=${_APP_URL}
      - --build-arg=NEXT_PUBLIC_FIREBASE_API_KEY=${_API_KEY}
      - --build-arg=NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN=lsv-oss-prod.firebaseapp.com
      - --build-arg=NEXT_PUBLIC_FIREBASE_PROJECT_ID=lsv-oss-prod
      - --build-arg=NEXT_PUBLIC_FIREBASE_APP_ID=${_APP_ID}
      - -t
      - australia-southeast1-docker.pkg.dev/lsv-oss-prod/lsv-oss/app:${SHORT_SHA}
      - -t
      - australia-southeast1-docker.pkg.dev/lsv-oss-prod/lsv-oss/app:latest
