#!/usr/bin/env bun
/**
 * Who may open a static app served through the gate (see src/lib/static-app.ts).
 *
 *   bun run scripts/app-access.ts list   <app>
 *   bun run scripts/app-access.ts grant  <app> <email> ["Display Name"]
 *   bun run scripts/app-access.ts revoke <app> <email>
 *
 * A grant is the app's slug in the member's `apps` list on the allow-list
 * (`members/<email>`). Granting to someone who is not yet on the allow-list
 * adds them as an ordinary member, which needs the display name. Revoking
 * leaves their membership in place. Both take effect on the person's next
 * request; nothing is redeployed.
 *
 * Auth: gcloud ADC (or GOOGLE_APPLICATION_CREDENTIALS) with datastore access
 * to the project named by --project, NEXT_PUBLIC_FIREBASE_PROJECT_ID or
 * GOOGLE_CLOUD_PROJECT. Default project: lsv-oss-prod.
 */
import { initializeApp, applicationDefault } from "firebase-admin/app";
import { FieldValue, getFirestore } from "firebase-admin/firestore";

const KNOWN_APPS = ["limsoc-permission-assist"];

const args = process.argv.slice(2);
const pi = args.indexOf("--project");
const projectId = (pi >= 0 ? args.splice(pi, 2)[1] : undefined) ?? process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID ?? process.env.GOOGLE_CLOUD_PROJECT ?? "lsv-oss-prod";
const [verb, app, emailArg, displayName] = args;

function usage(): never {
  console.error('usage: bun run scripts/app-access.ts list|grant|revoke <app> [email] ["Display Name"] [--project id]');
  process.exit(2);
}
if (!verb || !app || !["list", "grant", "revoke"].includes(verb)) usage();
if (!KNOWN_APPS.includes(app)) {
  console.error(`Unknown app "${app}". Known: ${KNOWN_APPS.join(", ")}`);
  process.exit(2);
}

initializeApp({ credential: applicationDefault(), projectId });
const members = getFirestore().collection("members");

if (verb === "list") {
  const snap = await members.where("apps", "array-contains", app).get();
  if (snap.empty) console.log(`No one has access to ${app}.`);
  for (const d of snap.docs) console.log(`${d.get("email")}\t${d.get("displayName")}\t${d.get("role")}`);
  process.exit(0);
}

const email = (emailArg ?? "").toLowerCase().trim();
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) usage();
const ref = members.doc(email);
const snap = await ref.get();

if (verb === "grant") {
  if (!snap.exists) {
    if (!displayName) {
      console.error(`${email} is not on the allow-list yet. Give a display name to add them: grant ${app} ${email} "First Last"`);
      process.exit(2);
    }
    await ref.set({ email, displayName: displayName.trim(), role: "member", apps: [app], addedBy: "app-access script", addedAt: new Date().toISOString() });
    console.log(`member added: ${email} (${displayName.trim()}), granted ${app}`);
  } else {
    await ref.update({ apps: FieldValue.arrayUnion(app) });
    console.log(`granted ${app} to ${email}`);
  }
} else {
  if (!snap.exists) {
    console.log(`${email} is not on the allow-list; nothing to revoke.`);
  } else {
    await ref.update({ apps: FieldValue.arrayRemove(app) });
    console.log(`revoked ${app} from ${email}`);
  }
}
EOF
cat > test/static-app.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { createHash } from "node:crypto";
import { STATIC_APPS, bucketFor, buildCsp, contentTypeFor, hasAppGrant, inlineScriptHashes, resolveObject } from "../src/lib/static-app";

describe("resolveObject", () => {
  test("root is the page", () => {
    expect(resolveObject(undefined)).toBe("index.html");
    expect(resolveObject([])).toBe("index.html");
  });
  test("plain nested files of known types", () => {
    expect(resolveObject(["vendor", "xlsx.full.min.js"])).toBe("vendor/xlsx.full.min.js");
  });
  test("refuses traversal, hidden files, encoded separators and unknown types", () => {
    for (const bad of [[".."], ["..", "index.html"], ["vendor", "..", "x.js"], ["a..b.js"], [".env"], ["..%2f..%2fapi", "health"], ["a/b.js"], ["a\\b.js"], ["x.exe"], ["noext"], ["a b.js"], ["%2e%2e", "x.js"]]) {
      expect(resolveObject(bad)).toBeNull();
    }
  });
  test("refuses very deep paths", () => {
    expect(resolveObject(["a", "b", "c", "d", "e", "f", "g.js"])).toBeNull();
  });
});

describe("inlineScriptHashes", () => {
  const app = "\nvar a=1;\n";
  const html = `<script type="application/json" id="seed">{"x":"<script>alert(1)"}</script><script src="/v/x.js"></script><script>${app}</script>`;
  test("hashes executable inline scripts only", () => {
    const want = `'sha256-${createHash("sha256").update(app).digest("base64")}'`;
    expect(inlineScriptHashes(html)).toContain(want);
    // The data block and the external script contribute nothing a browser would run.
    expect(inlineScriptHashes(`<script type="application/json">{"a":1}</script><script src="x.js"></script>`)).toEqual([]);
  });
  test("normalises newlines the way the HTML parser does", () => {
    expect(inlineScriptHashes("<script>a\r\nb</script>")).toEqual(inlineScriptHashes("<script>a\nb</script>"));
  });
});

describe("buildCsp", () => {
  const csp = buildCsp(["'sha256-abc'"]);
  test("scripts are same-origin plus the given hashes", () => {
    expect(csp).toContain("script-src 'self' 'sha256-abc'");
    expect(csp.split(";").find((d) => d.trim().startsWith("script-src"))).not.toMatch(/unsafe-inline|unsafe-eval|https?:|\*/);
  });
  test("no network, framing, plugins, base or form targets", () => {
    for (const d of ["default-src 'none'", "connect-src 'none'", "object-src 'none'", "base-uri 'none'", "form-action 'none'", "frame-ancestors 'none'"]) {
      expect(csp).toContain(d);
    }
  });
});

describe("access", () => {
  test("a grant is explicit and per app", () => {
    expect(hasAppGrant({ apps: ["limsoc-permission-assist"] }, "limsoc-permission-assist")).toBe(true);
    expect(hasAppGrant({ apps: [] }, "limsoc-permission-assist")).toBe(false);
    expect(hasAppGrant({}, "limsoc-permission-assist")).toBe(false);
    expect(hasAppGrant({ apps: ["other"] }, "limsoc-permission-assist")).toBe(false);
    expect(hasAppGrant(null, "limsoc-permission-assist")).toBe(false);
  });
});

describe("configuration", () => {
  test("bucket follows the project", () => {
    process.env.GOOGLE_CLOUD_PROJECT = "lsv-oss-prod";
    expect(bucketFor(STATIC_APPS["limsoc-permission-assist"])).toBe("lsv-oss-prod-limsoc-permission-assist");
  });
  test("content types", () => {
    expect(contentTypeFor("index.html")).toBe("text/html; charset=utf-8");
    expect(contentTypeFor("vendor/xlsx.full.min.js")).toBe("text/javascript; charset=utf-8");
    expect(contentTypeFor("x.php")).toBeNull();
  });
});
EOF
