import puppeteer from "/home/nicholas-wood/.claude/PAI/TOOLS/DrawioExport/node_modules/puppeteer/lib/esm/puppeteer/puppeteer.js";
import { readdirSync, readFileSync } from "node:fs";
const [url, csv, dl, cookie] = process.argv.slice(2);
const browser = await puppeteer.launch({ headless: true, args: ["--no-sandbox"] });
const page = await browser.newPage();
if (cookie) { const u = new URL(url); await browser.setCookie({ name: "session", value: cookie, domain: u.hostname, path: "/", secure: true, httpOnly: true }); }
const cdp = await page.createCDPSession();
await cdp.send("Browser.setDownloadBehavior", { behavior: "allow", downloadPath: dl, eventsEnabled: true });
const consoleMsgs = [], requests = [], failed = [];
page.on("console", (m) => consoleMsgs.push(`${m.type()}: ${m.text()}`));
page.on("pageerror", (e) => consoleMsgs.push(`pageerror: ${e.message}`));
page.on("request", (r) => requests.push(r.url()));
page.on("requestfailed", (r) => failed.push(`${r.url()} ${r.failure()?.errorText}`));
await page.evaluateOnNewDocument(() => { window.__csp = []; document.addEventListener("securitypolicyviolation", (e) => window.__csp.push(`${e.violatedDirective} ${e.blockedURI}`)); });
const res = await page.goto(url, { waitUntil: "networkidle0" });
const out = { finalUrl: page.url(), status: res.status() };
out.title = await page.title();
out.src = await page.$eval("#src", (e) => e.textContent);
out.mode = await page.$eval("#mode", (e) => e.textContent);
out.xlsxLoaded = await page.evaluate(() => !!window.XLSX && window.XLSX.version);
out.exampleStats = await page.$eval("#stats", (e) => e.innerText.replace(/\s+/g, " "));
out.newCountExample = await page.$eval("#newCount", (e) => e.textContent);
const input = await page.$("#file"); await input.uploadFile(csv);
await page.waitForFunction(() => !document.querySelector("#src").textContent.startsWith("Example"), { timeout: 10000 });
out.srcAfterUpload = await page.$eval("#src", (e) => e.textContent);
out.statsAfterUpload = await page.$eval("#stats", (e) => e.innerText.replace(/\s+/g, " "));
out.newCountAfterUpload = await page.$eval("#newCount", (e) => e.textContent);
out.warns = await page.$eval("#warns", (e) => e.hidden ? "" : e.innerText.slice(0, 200));
await page.click("#dlx"); await new Promise((r) => setTimeout(r, 2500));
await page.click("#dlc"); await new Promise((r) => setTimeout(r, 2500));
out.downloads = readdirSync(dl).map((f) => { const b = readFileSync(`${dl}/${f}`); return { name: f, bytes: b.length, head: f.endsWith(".csv") ? b.subarray(0, 22).toString() : b.subarray(0, 4).toString("hex") }; });
out.cspViolations = await page.evaluate(() => window.__csp);
out.console = consoleMsgs.slice(0, 10);
out.requestOrigins = [...new Set(requests.map((r) => r.startsWith("blob:") ? "blob:(own origin)" : r.startsWith("data:") ? "data:" : new URL(r).origin))];
out.requests = requests.filter((r) => !r.startsWith("blob:")).map((r) => r.slice(0, 110));
out.failed = failed;
out.localStorageKeys = await page.evaluate(() => Object.keys(localStorage));
// Prove the policy bites: a fetch and an injected inline script must both be refused.
out.fetchBlocked = await page.evaluate(() => fetch("https://example.com/").then(() => "ALLOWED", (e) => "blocked: " + e.message));
out.inlineBlocked = await page.evaluate(() => { const s = document.createElement("script"); s.textContent = "window.__pwn=1"; document.body.appendChild(s); return window.__pwn ? "RAN" : "blocked"; });
out.cspViolationsAfterNegativeTests = await page.evaluate(() => window.__csp);
await page.screenshot({ path: `${dl}/../page.png` });
console.log(JSON.stringify(out, null, 1));
await browser.close();
EOF
