# ── Firebase Hosting: the front door for nicholaswood.com.au ─────────────────
# Cloud Run domain mappings are not available in australia-southeast1, so the
# custom domain terminates at Firebase Hosting (free tier, Google-managed TLS)
# and everything under /lsv/ is rewritten to the Cloud Run service. Hosting
# forwards only the `__session` cookie, which is why the app uses that name.
resource "google_firebase_hosting_site" "default" {
  provider = google-beta
  project  = var.project_id
  site_id  = var.project_id
}

resource "google_firebase_hosting_version" "front" {
  provider = google-beta
  site_id  = google_firebase_hosting_site.default.site_id
  config {
    redirects {
      glob        = "/"
      status_code = 302
      location    = local.base_path
    }
    rewrites {
      glob = "/lsv/**"
      run {
        service_id = google_cloud_run_v2_service.app.name
        region     = var.region
      }
    }
  }
}

resource "google_firebase_hosting_release" "front" {
  provider     = google-beta
  site_id      = google_firebase_hosting_site.default.site_id
  version_name = google_firebase_hosting_version.front.name
  message      = "Rewrite /lsv/** to Cloud Run"
}

resource "google_firebase_hosting_custom_domain" "root" {
  provider              = google-beta
  project               = var.project_id
  site_id               = google_firebase_hosting_site.default.site_id
  custom_domain         = var.domain
  wait_dns_verification = false
}
=== middleware
import { NextResponse, type NextRequest } from "next/server";

/**
 * Edge gate: anything under the app that is not an auth surface needs a
 * session cookie to exist. The cookie is verified properly in getAuthUser();
 * this just stops anonymous requests from reaching data or page handlers at
 * all, including the static vendor files that only signed-in pages load.
 */
const PUBLIC_PREFIXES = ["/sign-in", "/auth/", "/not-a-member", "/logout", "/api/auth/", "/api/health", "/api/cron/", "/_next/", "/favicon"];

export function middleware(request: NextRequest) {
  const path = request.nextUrl.pathname.replace(/^\/lsv\/dailysummary/, "") || "/";
  if (PUBLIC_PREFIXES.some((p) => path.startsWith(p))) return NextResponse.next();
  if (request.cookies.get("__session")?.value) return NextResponse.next();
  if (path.startsWith("/api/")) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  // Built from the configured origin, not the request host: behind Firebase
  // Hosting the request arrives with the Cloud Run hostname.
  const origin = process.env.NEXT_PUBLIC_APP_URL || request.nextUrl.origin;
  return NextResponse.redirect(`${origin}/lsv/dailysummary/sign-in`, { status: 303 });
}

export const config = {
  matcher: ["/((?!_next/static|_next/image).*)"],
};
