=== next.config.ts
import type { NextConfig } from "next";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

// Served under this prefix on nicholaswood.com.au. The app uses hash routing
// inside the page, so the prefix is the only path the server needs to own.
export const BASE_PATH = "/lsv/dailysummary";

let version = "dev";
try {
  const manifest = JSON.parse(readFileSync(resolve(__dirname, ".release-please-manifest.json"), "utf8"));
  version = manifest["."] ?? "dev";
} catch {
  // manifest absent in some environments
}

const nextConfig: NextConfig = {
  output: "standalone",
  basePath: BASE_PATH,
  poweredByHeader: false,
  // Keep the Admin SDK and friends as runtime requires rather than bundling
  // them into route chunks; they resolve from node_modules in the image.
  serverExternalPackages: ["firebase-admin", "jwks-rsa", "jose", "google-auth-library", "resend"],
  env: {
    NEXT_PUBLIC_APP_VERSION: version,
    NEXT_PUBLIC_BASE_PATH: BASE_PATH,
  },
  // Static headers for everything except the OSS page itself, which sets a
  // per-request nonce CSP in its route handler (see src/app/route.ts).
  async headers() {
    return [
      // Firebase Hosting's CDN sits in front; nothing behind sign-in may be stored by it.
      { source: "/api/:path*", headers: [{ key: "Cache-Control", value: "private, no-store" }] },
      { source: "/vendor/:path*", headers: [{ key: "Cache-Control", value: "private, max-age=3600" }] },
      {
        source: "/:path*",
        headers: [
          { key: "X-Content-Type-Options", value: "nosniff" },
          { key: "X-Frame-Options", value: "DENY" },
          { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
          { key: "Permissions-Policy", value: "camera=(), microphone=(), geolocation=()" },
          { key: "Strict-Transport-Security", value: "max-age=31536000; includeSubDomains" },
        ],
      },
    ];
  },
};

export default nextConfig;
=== e2e-probe head
#!/usr/bin/env bun
/**
 * End-to-end probe of a deployed instance without email access.
 *
 *   APP_URL=https://host bun run scripts/e2e-probe.ts member@example.com
 *
 * Mints a Firebase custom token for the member (Admin SDK via IAM signBlob as
 * the runtime SA), exchanges it for an ID token with the Identity Toolkit REST
 * API, then drives the real HTTP surface: /api/auth/session → cookie,
 * authenticated page (CSP, nonce, injected globals), /api/auth/firebase-token
 * (POST only, Origin-checked), /api/members, anonymous refusals, logout.
 * Prints PASS/FAIL lines; exits non-zero on any FAIL.
 */
import { initializeApp as initAdmin, applicationDefault } from "firebase-admin/app";
import { getAuth as getAdminAuth } from "firebase-admin/auth";

const APP_URL = (process.env.APP_URL ?? "").replace(/\/$/, "");
const BASE = `${APP_URL}/lsv/dailysummary`;
const email = process.argv[2]?.toLowerCase();
const apiKey = process.env.NEXT_PUBLIC_FIREBASE_API_KEY;
const projectId = process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID ?? "lsv-oss-prod";
if (!APP_URL || !email || !apiKey) throw new Error("APP_URL, NEXT_PUBLIC_FIREBASE_API_KEY and a member email are required");

initAdmin({ credential: applicationDefault(), projectId, serviceAccountId: `lsv-oss-run@${projectId}.iam.gserviceaccount.com` });
