import { SITE_HEADERS, buildCsp, contentTypeFor, fetchObject, inlineScriptHashes, resolveObject, siteBucket } from "@/lib/site";

export const dynamic = "force-dynamic";

/**
 * Serves LIMSOC Permission Assist from its private bucket to signed-in
 * members. Every path that is not a sign-in surface lands here.
