#!/usr/bin/env bun
/** CI: every file in site/ matches the SHA-256 recorded in poc.json (when present), so what deploys is what was packaged. */
import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";

if (!existsSync("poc.json")) {
  console.log("no poc.json (template); skipping");
  process.exit(0);
}
const manifest = JSON.parse(readFileSync("poc.json", "utf8")) as { files: { path: string; sha256: string }[]; build: { command: string | null } };
if (manifest.build.command) {
  console.log("built POC: hashes are checked on the source at intake; skipping");
  process.exit(0);
}
let bad = 0;
for (const f of manifest.files) {
  const p = `site/${f.path}`;
  const got = existsSync(p) ? createHash("sha256").update(readFileSync(p)).digest("hex") : "missing";
  if (got !== f.sha256) {
    bad++;
    console.log(`MISMATCH ${p}: ${got}`);
  }
}
console.log(bad ? `${bad} mismatches` : `${manifest.files.length} files match poc.json`);
process.exit(bad ? 1 : 0);
