(function(){
var $=function(id){return document.getElementById(id)};
var SU=/^superuser$/i, LAST=/^superuser\s*\(do not update manually\)$/i, LAST_NAME='Superuser (Do not update manually)';
var data=null, P=[], byCode={}, groups=[], orig={}, cur={}, include={}, suName=null, lastName=null, fullSet=new Set(), oldSet=null;
var KEY='lsvperm2:';
var DICT={};
function toast(t){var e=$('toast');e.textContent=t;e.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(function(){e.hidden=true},3200)}
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function short(n){return n.replace(/^\d\d-\d\d-/,'')}
function isSU(n){return SU.test(n.trim())} function isLast(n){return LAST.test(n.trim())}
function special(n){return isSU(n)||isLast(n)}

// Labels for codenames, from a LIMSOC staging read on 14 Nov 2026. Unknown codenames are grouped by their model name.
(function(){try{var s=JSON.parse($('seed').textContent);s.perms.forEach(function(p){var parts=p[1].split(' | '),n=parts.length,o={code:parts[n-1]};if(n>=4){o.app=parts[0];o.model=parts[1];o.desc=parts.slice(2,n-1).join(' | ')}else if(n==3){o.app='Other';o.model=parts[0];o.desc=parts[1]}else{o.app='Other';o.model='';o.desc=''}DICT[o.code]=o})}catch(e){}})();
function permInfo(code){
  if(DICT[code])return DICT[code];
  var m=code.match(/^(add|change|delete|view)_(.+)$/);
  return {code:code,app:'Not seen before',model:m?m[2]:'custom',desc:''};
}
function store(){dirty();try{localStorage.setItem(KEY+data.sig,JSON.stringify(Object.keys(cur).reduce(function(o,k){o[k]=[...cur[k]];return o},{})))}catch(e){}}

// data = {source, sig, groups:[{name, perms:[codenames]}]}
function load(d,isExample){
  var w=[],info=[];
  data=d; groups=d.groups.slice().sort(function(a,b){return a.name.localeCompare(b.name)});
  var su=groups.filter(function(g){return isSU(g.name)})[0], last=groups.filter(function(g){return isLast(g.name)})[0];
  if(!su)throw new Error('This export has no group called Superuser, so new permissions can\'t be worked out. Check you exported every group.');
  suName=su.name;
  fullSet=new Set(); groups.forEach(function(g){g.perms.forEach(function(c){fullSet.add(c)})});
  var extra=[...fullSet].filter(function(c){return su.perms.indexOf(c)<0});
  if(extra.length)w.push('Superuser is missing '+extra.length+' permission'+(extra.length>1?'s':'')+' that other groups have. Did you click <b>Choose all</b> on Superuser before exporting? The import file still sets Superuser to everything here.');
  if(last){lastName=last.name;oldSet=new Set(last.perms)}
  else{
    lastName=null;
    try{oldSet=new Set(JSON.parse($('base').textContent))}catch(e){oldSet=new Set()}
    info.push('No <b>'+LAST_NAME+'</b> group in this export, so this run compares against the list in your spreadsheet (sheet Groups - 3.24.13, '+oldSet.size+' permissions). The import file creates <b>'+LAST_NAME+'</b> for next time.');
  }
  var newCount=[...fullSet].filter(function(c){return !oldSet.has(c)}).length;
  var gone=[...oldSet].filter(function(c){return !fullSet.has(c)});
  if(!newCount&&last)info.push('Nothing is new since the last run. If you expected new permissions, check you clicked <b>Choose all</b> on Superuser before exporting.');
  if(gone.length)info.push(gone.length+' permission'+(gone.length>1?'s are':' is')+' no longer in LIMSOC since the last run: '+gone.map(function(c){return '<code>'+esc(c)+'</code>'}).join(', '));
  P=[...fullSet].map(permInfo).sort(function(a,b){return (a.app+'|'+a.model+'|'+a.code).localeCompare(b.app+'|'+b.model+'|'+b.code)});
  byCode={};P.forEach(function(p){byCode[p.code]=p});
  orig={};cur={};include={};
  groups.forEach(function(g){orig[g.name]=new Set(g.perms)});dirty();groups.forEach(function(g){cur[g.name]=ownFrom(orig,g.name)});dirty();
  try{var saved=JSON.parse(localStorage.getItem(KEY+d.sig)||'null');if(saved)Object.keys(saved).forEach(function(k){if(cur[k])cur[k]=new Set(saved[k])})}catch(e){}
  dirty();
  $('warns').innerHTML=w.join('<br>');$('warns').hidden=!w.length;
  $('infos').innerHTML=info.join('<br><br>');$('infos').hidden=!info.length;
  $('src').innerHTML=(isExample?'Example: ':'')+'<b>'+esc(d.source)+'</b>';
  $('fileinfo').textContent=isExample?'Showing example data from LIMSOC staging. Upload your export to start.':'Loaded '+d.source;
  $('gsel').innerHTML=groups.filter(function(g){return !special(g.name)}).map(function(g){return '<option value="'+esc(g.name)+'">'+esc(g.name)+'</option>'}).join('');
  renderAll();
}
