  var all=P.map(function(p){return p.code}).join(',');
  rows.push([suName,all]); rows.push([lastName||LAST_NAME,all]);
  return rows;
}
function renderStats(){
  var nn=newPerms().length, ch=editable().filter(function(g){var c=changed(g.name);return c.add||c.rem}).length;
  $('newCount').textContent=nn;

