=== bridge script
/**
 * Browser side of the backend bridge: defines window.claude for a page that
 * was built in claude.ai, backed by this host's own API (same origin, so
 * the CSP stays 'self'). Pattern from the Service Summary's src/bridge/.
 *
 * Implemented: storage (get/set/delete/list, per user or { shared: true }),
 * user, downloads. Anything else (for example complete) throws a clear
 * error: the poc-deploy skill must wire it deliberately, because it needs a
 * secret or a model call the platform does not provide by default.
 */
export const BRIDGE_SCRIPT = `(() => {
  const api = async (path, init) => {
    const r = await fetch(path, { credentials: "same-origin", headers: { "Content-Type": "application/json" }, ...init });
    if (r.status === 401) { window.location.assign("/sign-in"); throw new Error("signed out"); }
    if (!r.ok) throw new Error("bridge " + path + " " + r.status);
    return r.json();
  };
  const q = (o) => new URLSearchParams(Object.entries(o).filter(([, v]) => v !== undefined && v !== false)).toString();
  const storage = {
    get: async (key, opt = {}) => (await api("/api/bridge/storage?" + q({ key, shared: opt.shared }))).value,
    set: (key, value, opt = {}) => api("/api/bridge/storage", { method: "PUT", body: JSON.stringify({ key, value, shared: !!opt.shared }) }),
    delete: (key, opt = {}) => api("/api/bridge/storage", { method: "DELETE", body: JSON.stringify({ key, shared: !!opt.shared }) }),
    list: async (prefix = "", opt = {}) => (await api("/api/bridge/storage?" + q({ prefix, shared: opt.shared }))).keys,
  };
  const user = { get: () => api("/api/bridge/user"), id: async () => (await api("/api/bridge/user")).id };
  const downloads = {
    save: async (name, data) => {
      const blob = data instanceof Blob ? data : new Blob([data]);
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = name;
      document.body.appendChild(a);
      a.click();
      setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1000);
    },
  };
  const known = { storage, user, downloads, use: (name) => known[name] };
  window.claude = new Proxy(known, {
    get(t, p) {
      if (p in t) return t[p];
      return () => { throw new Error("window.claude." + String(p) + " is not available on this host; ask the platform owner to wire it"); };
    },
  });
  window.storage = window.storage || storage;
})();
`;
