// Built page + the repo's real bridge script + an in-memory store that follows the host's /api/bridge contract.
import { readFileSync } from "node:fs";
import { BRIDGE_SCRIPT } from "/home/nicholas-wood/.claude/jobs/64af022a/tmp/pp/src/lib/bridge-script";
const dir = process.argv[2]; const store = new Map<string, unknown>();
const who = (r: Request) => (r.headers.get("cookie") ?? "").match(/who=([^;]+)/)?.[1] ?? "";
const j = (s: number, b: unknown) => new Response(JSON.stringify(b), { status: s, headers: { "Content-Type": "application/json" } });
Bun.serve({ port: 3955, hostname: "127.0.0.1", async fetch(req) {
  const u = new URL(req.url);
  if (u.pathname === "/poc-bridge.js") return new Response(BRIDGE_SCRIPT, { headers: { "Content-Type": "text/javascript" } });
  if (u.pathname === "/api/bridge/user") return who(req) ? j(200, { id: "u-" + who(req), email: decodeURIComponent(who(req)), role: "member" }) : j(401, {});
  if (u.pathname === "/api/bridge/storage") {
    if (!who(req)) return j(401, {});
    const mut = req.method !== "GET"; const b: any = mut ? await req.json().catch(() => null) : null;
    const key = String(mut ? b?.key ?? "" : u.searchParams.get("key") ?? ""); const shared = mut ? b?.shared === true : u.searchParams.get("shared") === "true";
    const scope = shared ? "shared:" : `user:${who(req)}:`;
    if (!/^[\w.:/-]{1,200}$/.test(key)) return j(400, { error: "key" });
    if (req.method === "GET") return j(200, { key, value: store.get(scope + key) ?? null });
    if (JSON.stringify(b?.value ?? null).length > 500_000) return j(413, { error: "value too large" });
    store.set(scope + key, b?.value ?? null); return j(200, { ok: true });
  }
  if (u.pathname === "/__store") return j(200, [...store.entries()].map(([k, v]) => [k, JSON.stringify(v).length]));
  try { const f = u.pathname === "/" ? "index.html" : u.pathname.slice(1); let body: any = readFileSync(`${dir}/${f}`);
    if (f === "index.html") { let h = body.toString("utf8"); const m = /<head[^>]*>/i.exec(h)!; body = h.slice(0, m.index + m[0].length) + '<script src="/poc-bridge.js"></script>' + h.slice(m.index + m[0].length); }
    return new Response(body, { headers: { "Content-Type": f.endsWith(".js") ? "text/javascript" : "text/html; charset=utf-8", "Content-Security-Policy": f === "index.html" ? "connect-src 'self'" : "" } });
  } catch { return new Response("nf", { status: 404 }); } } });
EOF
