out.alice_downloads = readdirSync(dlA).map((f) => `${f} (${readFileSync(`${dlA}/${f}`).length} B)`);
out.bob_uploadsHandEditedExport = await bob.upload(B);
out.alice_uploadsUnchangedExport = await alice.upload(C);
out.store = await (await fetch(U + "__store")).json();
out.localStorageInAlice = await alice.page.evaluate(() => Object.keys(localStorage));
out.errors = { alice: alice.errs, bob: bob.errs };
console.log(JSON.stringify(out, null, 1)); await browser.close();
EOF
