# LIMSOC Permission Assist — infrastructure
#
# Same shape as AccessBuddy and the LSV Operational Service Summary: one Cloud
# Run service in australia-southeast1 that enforces its own sign-in, Secret
# Manager for secrets, Artifact Registry for images, Firebase Hosting as the
# front door for the custom domain, WIF for the GitHub deploy. In its own
# project, sharing nothing with either of them.
#
# What is specific here: the page itself is not in the image. It is in a
# private bucket that only the runtime account can read.
#
# First-time bootstrap is in DEPLOY.md. Then:
#   terraform init -backend-config="bucket=limsoc-pa-prod-tfstate"
#   terraform apply -var-file=prod.tfvars

terraform {
  required_version = ">= 1.5"
  required_providers {
    google      = { source = "hashicorp/google", version = "~> 6.0" }
    google-beta = { source = "hashicorp/google-beta", version = "~> 6.0" }
    random      = { source = "hashicorp/random", version = "~> 3.6" }
  }
  backend "gcs" {
    prefix = "terraform/state"
  }
}

provider "google" {
  project               = var.project_id
  region                = var.region
  user_project_override = true
  billing_project       = var.project_id
}

provider "google-beta" {
  project               = var.project_id
  region                = var.region
  user_project_override = true
  billing_project       = var.project_id
}

locals {
  service_name = "limsoc-pa-${var.environment}"
  default_host = "${var.project_id}.web.app"
  # The address members use. Until the custom domain's DNS record exists this is the web.app address.
  app_host = var.serve_on_domain ? var.domain : local.default_host
  app_url  = "https://${local.app_host}"
}

# ── APIs ──────────────────────────────────────────────────────────────────────
resource "google_project_service" "apis" {
  for_each = toset([
    "run.googleapis.com",
    "firestore.googleapis.com",
    "firebase.googleapis.com",
    "firebasehosting.googleapis.com",
    "identitytoolkit.googleapis.com",
    "firebaserules.googleapis.com",
    "secretmanager.googleapis.com",
    "artifactregistry.googleapis.com",
    "cloudbuild.googleapis.com",
    "storage.googleapis.com",
    "iam.googleapis.com",
    "iamcredentials.googleapis.com",
    "sts.googleapis.com",
    "logging.googleapis.com",
    "cloudresourcemanager.googleapis.com",
    "serviceusage.googleapis.com",
  ])
  service            = each.key
  disable_on_destroy = false
}

# ── Firebase: sign-in (email link only) and the web app config ───────────────
resource "google_firebase_project" "default" {
  provider   = google-beta
  project    = var.project_id
  depends_on = [google_project_service.apis]
}

resource "google_firebase_web_app" "app" {
  provider        = google-beta
  project         = var.project_id
  display_name    = "LIMSOC Permission Assist"
  deletion_policy = "DELETE"
  depends_on      = [google_firebase_project.default]
}

data "google_firebase_web_app_config" "app" {
