import pathlib
p=pathlib.Path('page/src/app.js'); s=p.read_text()
def once(a,b):
    global s
    assert s.count(a)==1,(a[:80],s.count(a)); s=s.replace(a,b)
# 1) one place decides what goes in the import file
old1="var c=changed(g.name);var inc=include[g.name]===undefined?!!(c.add||c.rem):include[g.name];"
assert s.count(old1)==2
s=s.replace(old1,"var inc=inFile(g.name);")
once("var c=changed(g.name), inc=include[g.name]===undefined?!!(c.add||c.rem):include[g.name];","var c=changed(g.name), inc=inFile(g.name);")
# 2) don't record an added group that isn't going into the import file
once("groups.forEach(function(g){if(special(g.name))return;var inc=inFile(g.name);\n    exp[g.name]=","groups.forEach(function(g){if(special(g.name))return;var inc=inFile(g.name);if(!inc&&isAdded(g.name))return;\n    exp[g.name]=")
# 3) helpers before load()
once("// data = {source, sig, groups:[{name, perms:[codenames]}]}\nfunction load(d,isExample){",'''// Groups added in this page: they aren't in LIMSOC yet, so they go into the import file and LIMSOC creates them on import.
// Removing and renaming groups is done in LIMSOC admin. Like ticks, added groups are kept in this browser for this file.
var addedNames=[];
function isAdded(n){return addedNames.indexOf(n)>-1}
function saveAdded(){try{localStorage.setItem(KEY+data.sig+':added',JSON.stringify(addedNames))}catch(e){}}
function sameName(a,b){return a.trim().toLowerCase()===b.trim().toLowerCase()}
function sortGroups(){groups.sort(function(a,b){return a.name.localeCompare(b.name)})}
// In the import file: what was ticked in step 4, otherwise every changed group and every added group.
function inFile(n){if(include[n]!==undefined)return include[n];var c=changed(n);return isAdded(n)||!!(c.add||c.rem)}
function fillGroupSelects(){
  var gs=editable(),el=$('gsel'),v=el.value;
  el.innerHTML=gs.map(function(g){return '<option value="'+esc(g.name)+'">'+esc(g.name)+(isAdded(g.name)?' (new)':'')+'</option>'}).join('');
  if(gs.some(function(g){return g.name===v}))el.value=v;
  var fr=$('newGroupFrom'),fv=fr.value;
  fr.innerHTML='<option value="">no permissions</option>'+gs.map(function(g){return '<option value="'+esc(g.name)+'">the permissions of '+esc(g.name)+'</option>'}).join('');
  if(gs.some(function(g){return g.name===fv}))fr.value=fv;
}
function addGroup(raw,from){
  var name=String(raw||'').replace(/\\s+/g,' ').trim();
  if(!name){toast('Type a name for the new group.');return false}
  if(name.length>150){toast('Group names can be up to 150 characters.');return false}
  if(special(name)){toast('That name belongs to one of the Superuser groups.');return false}
  var clash=groups.filter(function(g){return sameName(g.name,name)})[0];
  if(clash){toast('There is already a group called '+clash.name+'.');return false}
  var start=from&&cur[from]?new Set(E(from)):new Set();
  dirty();groups.push({name:name,perms:[]});sortGroups();orig[name]=new Set();cur[name]=start;delete include[name];
  addedNames.push(name);saveAdded();store();
  fillGroupSelects();$('gsel').value=name;renderAll();
  toast('Added '+name+(start.size?' with '+start.size+' permissions':'')+'. It goes into the import file.');
  return true;
}
function removeAdded(n){
