rmSync(dl, { recursive: true, force: true }); await cdp.send("Browser.setDownloadBehavior", { behavior: "allow", downloadPath: dl }); await page.click("#dlc"); await wait(1800);
out.excludedNotInFile = !readFileSync(`${dl}/${readdirSync(dl).find((n) => n.endsWith(".csv"))}`, "utf8").includes("Excluded One");
await page.select("#gsel", "Excluded One"); await wait(150);
